2	
3	/** Held rather than re-looked-up, so the link lands in the pre-open note. */
4	export type EditorInsertTarget = {
5	  view: MarkdownView;
6	  from: EditorPosition;
7	  to: EditorPosition;
8	};
9	
10	/**
11	 * Call before the modal mounts, while the editor still owns the cursor.
12	 * `hasFocus()` is not part of the gate: opening the search from the command
13	 * palette means that palette already took focus.
14	 */
15	export const snapshotInsertTarget = (app: App): EditorInsertTarget | null => {
16	  const view = app.workspace.getActiveViewOfType(MarkdownView);
17	  // Reading mode has no cursor.
18	  if (!view || !view.file || view.getMode() !== "source") return null;
19	
20	  const { editor } = view;
21	  return {
22	    view,
23	    // A selection is replaced rather than left beside the link.
24	    from: editor.getCursor("from"),
25	    to: editor.getCursor("to"),
26	  };
27	};
