29	/** `generateMarkdownLink` is what honours the vault's link-format settings. */
30	export const insertLinkAtInsertTarget = ({
31	  app,
32	  file,
33	  target,
34	}: {
35	  app: App;
36	  file: TFile;
37	  target: EditorInsertTarget;
38	}): void => {
39	  const { view, from, to } = target;
40	  const sourceFile = view.file;
41	  if (!sourceFile) return;
42	
43	  const link = app.fileManager.generateMarkdownLink(file, sourceFile.path);
44	  const { editor } = view;
45	  editor.replaceRange(link, from, to);
46	
47	  app.workspace.setActiveLeaf(view.leaf, { focus: true });
48	  editor.setCursor({ line: from.line, ch: from.ch + link.length });
49	  editor.focus();
50	};
