 * Replace the first embed of `imageFile` in the active editor with a link to `targetFile`.
 */
const replaceImageEmbedInEditor = ({
  app,
  imageFile,
  targetFile,
}: {
  app: App;
  imageFile: TFile;
  targetFile: TFile;
}): void => {
  const activeView = app.workspace.getActiveViewOfType(MarkdownView);
  if (!activeView?.file) return;

  const cache = app.metadataCache.getFileCache(activeView.file);
  const embed = cache?.embeds?.find((e) => {
    const resolved = app.metadataCache.getFirstLinkpathDest(
      e.link,
      activeView.file!.path,
    );
    return resolved?.path === imageFile.path;
  });
  if (!embed) return;

  const from = activeView.editor.offsetToPos(embed.position.start.offset);
  const to = activeView.editor.offsetToPos(embed.position.end.offset);
  const linkText = app.metadataCache.fileToLinktext(
    targetFile,
    activeView.file.path,
  );
  activeView.editor.replaceRange(`[[${linkText}]]`, from, to);
};

const IMAGE_EXTENSIONS = /^(png|jpe?g|gif|svg|bmp|webp|avif|tiff?)$/i;

export const isImageFile = (file: TFile): boolean =>
  IMAGE_EXTENSIONS.test(file.extension);

/**
 * Open ModifyNodeModal to convert an image file into a discourse node.
 * Shared by file-menu "Convert into" and the hover icon on embedded images.
 *
 * Pass `disableExistingNodeSearch: true` from the file-explorer path because
 * the intent there is always to create a new node, not reuse an existing one.
 */
export const openConvertImageToNodeModal = ({
  plugin,
  imageFile,
  initialNodeType,
  disableExistingNodeSearch = false,
}: {
  plugin: DiscourseGraphPlugin;
  imageFile: TFile;
  initialNodeType?: DiscourseNode;
  disableExistingNodeSearch?: boolean;
}): void => {
  new ModifyNodeModal(plugin.app, {
    nodeTypes: plugin.settings.nodeTypes,
    plugin,
    initialTitle: "",
    initialNodeType,
    disableExistingNodeSearch,
    onSubmit: async ({
      nodeType: selectedType,
      title,
      selectedExistingNode,
    }) => {
      const targetFile =
        selectedExistingNode ??
        (await createDiscourseNode({
          plugin,
          nodeType: selectedType,
          text: title,
        }));

      if (!targetFile) return;

      const imageLink = plugin.app.metadataCache.fileToLinktext(
        imageFile,
        targetFile.path,
      );
      await plugin.app.vault.append(targetFile, `\n![[${imageLink}]]\n`);
      replaceImageEmbedInEditor({
        app: plugin.app,
        imageFile,
        targetFile,
      });
    },
  }).open();
};
=== internalLinkParsing ===
// Shared by the CM6 extensions that scan raw markdown for internal links.

/** Embeds are not matched: the leading `!` sits outside, so callers check it. */
export const INTERNAL_LINK_RE =
  /\[\[([^\]]+)\]\]|\[([^\]]+)\]\(([^)]+\.md(?:#[^)]*)?)\)/g;

/** Target of a wikilink or markdown link; any `#subpath` is left for parseLinktext. */
export const extractLinktext = (match: string): string => {
  if (match.startsWith("[[")) {
    const inner = match.slice(2, -2);
    const pipeIndex = inner.indexOf("|");
    return pipeIndex >= 0 ? inner.slice(0, pipeIndex) : inner;
  }

  const parenOpen = match.lastIndexOf("(");
  const rawPath = match.slice(parenOpen + 1, -1);
  try {
    return decodeURIComponent(rawPath);
  } catch {
    return rawPath;
  }
};

